        radial-gradient(circle at top left, rgba(31, 111, 91, 0.12), transparent 28%),
        radial-gradient(circle at top right, rgba(184, 122, 63, 0.12), transparent 26%),
        linear-gradient(180deg, #faf8f4 0%, var(--bg) 100%);
      min-height: 100vh;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; }

    .shell {
      width: min(calc(100% - 32px), var(--max));
      margin: 0 auto;
      padding: 20px 0 48px;
    }

    .topbar,
    .hero,
    .section,
    .footer {
      margin-bottom: 24px;
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      padding: 18px 22px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.72);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
      position: sticky;
      top: 16px;
      z-index: 10;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .brand-mark {
      width: 36px;
      height: 36px;
      border-radius: 12px;
      background: linear-gradient(135deg, var(--brand), #68a88e);
      display: grid;
      place-items: center;
      color: #fff;
      font-weight: 800;
    }

    .nav {
      display: flex;
      gap: 18px;
      color: var(--muted);
      flex-wrap: wrap;
      justify-content: center;
    }

    .actions {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .icon-btn,
    .pill,
    .cta,
    .ghost {
      border: 1px solid transparent;
      transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease, background 180ms ease;
    }

    .icon-btn {
      width: 42px;
      height: 42px;
      border-radius: 999px;
      background: #fff;
      border-color: var(--line);
      display: grid;
      place-items: center;
      cursor: pointer;
    }

    .hero {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 24px;
      min-height: 640px;
    }

    .hero-copy,
    .hero-visual,
    .card,
    .deal-card,
    .story-card {
      border: 1px solid var(--line);
      background: var(--surface);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
