    .hero-copy {
      border-radius: 32px;
      padding: 38px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 26px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      color: var(--brand);
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.78rem;
