  <title>Atelier — Modern Retail Home</title>
  <meta name="description" content="A modern ecommerce homepage for a premium retail brand." />
  <style>
    :root {
      --bg: #f5f1ea;
      --surface: rgba(255, 255, 255, 0.78);
      --surface-strong: #ffffff;
      --text: #171717;
      --muted: #66615b;
      --line: rgba(23, 23, 23, 0.1);
      --brand: #1f6f5b;
      --brand-dark: #144b3e;
      --accent: #b87a3f;
      --shadow: 0 20px 60px rgba(23, 23, 23, 0.08);
      --radius-xl: 28px;
      --radius-lg: 20px;
      --radius-md: 16px;
      --max: 1200px;
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(31, 111, 91, 0.12), transparent 28%),
        radial-gradient(circle at top right, rgba(184, 122, 63, 0.12), transparent 26%),
        linear-gradient(180deg, #faf8f4 0%, var(--bg) 100%);
      min-height: 100vh;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; }

    .shell {
      width: min(calc(100% - 32px), var(--max));
      margin: 0 auto;
      padding: 20px 0 48px;
    }

    .topbar,
    .hero,
    .section,
    .footer {
      margin-bottom: 24px;
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      padding: 18px 22px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.72);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
      position: sticky;
      top: 16px;
      z-index: 10;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .brand-mark {
      width: 36px;
      height: 36px;
      border-radius: 12px;
      background: linear-gradient(135deg, var(--brand), #68a88e);
      display: grid;
      place-items: center;
      color: #fff;
      font-weight: 800;
    }

    .nav {
      display: flex;
      gap: 18px;
      color: var(--muted);
      flex-wrap: wrap;
      justify-content: center;
    }

    .actions {
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .icon-btn,
    .pill,
    .cta,
    .ghost {
      border: 1px solid transparent;
      transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease, background 180ms ease;
    }

    .icon-btn {
      width: 42px;
      height: 42px;
      border-radius: 999px;
      background: #fff;
      border-color: var(--line);
      display: grid;
      place-items: center;
      cursor: pointer;
    }

    .hero {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 24px;
      min-height: 640px;
    }

    .hero-copy,
    .hero-visual,
    .card,
    .deal-card,
    .story-card {
      border: 1px solid var(--line);
      background: var(--surface);
      backdrop-filter: blur(18px);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      border-radius: 32px;
      padding: 38px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 26px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      color: var(--brand);
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 0.78rem;
    }

    .eyebrow::before {
      content: "";
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: currentColor;
      box-shadow: 0 0 0 8px rgba(31, 111, 91, 0.12);
    }

    h1 {
      font-size: clamp(3rem, 6vw, 5.8rem);
      line-height: 0.94;
      margin: 10px 0 18px;
      max-width: 10ch;
      letter-spacing: -0.06em;
    }

    .lead {
      max-width: 54ch;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.65;
      margin: 0;
    }

    .hero-actions {
      display: flex;
      gap: 14px;
      flex-wrap: wrap;
      align-items: center;
    }

    .cta,
    .ghost {
      border-radius: 999px;
      padding: 14px 22px;
      font-weight: 700;
      cursor: pointer;
    }

    .cta {
      background: var(--text);
      color: #fff;
      box-shadow: 0 16px 30px rgba(23, 23, 23, 0.18);
    }

    .ghost {
      background: rgba(255, 255, 255, 0.66);
      border-color: var(--line);
      color: var(--text);
    }

    .hero-stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 12px;
    }

    .stat {
      padding: 18px;
      border-radius: 20px;
      background: rgba(255, 255, 255, 0.62);
      border: 1px solid var(--line);
    }

    .stat strong {
      display: block;
      font-size: 1.3rem;
      margin-bottom: 6px;
    }

    .stat span,
    .meta,
    .card p,
    .deal-card p,
    .story-card p {
      color: var(--muted);
    }

    .hero-visual {
      border-radius: 32px;
      padding: 22px;
      display: grid;
      gap: 18px;
      grid-template-rows: 1fr auto;
      overflow: hidden;
      position: relative;
    }

    .visual-panel {
      border-radius: 28px;
      background:
        radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.95), transparent 28%),
        radial-gradient(circle at 80% 15%, rgba(255, 225, 198, 0.7), transparent 18%),
        linear-gradient(160deg, #dbc6b6 0%, #f2e8dc 45%, #d8e4de 100%);
      position: relative;
      min-height: 430px;
      overflow: hidden;
    }

    .visual-panel::before,
    .visual-panel::after {
      content: "";
      position: absolute;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.42);
      filter: blur(2px);
    }

    .visual-panel::before {
      width: 280px;
      height: 280px;
      right: -40px;
      bottom: -60px;
    }

    .visual-panel::after {
      width: 170px;
      height: 170px;
      left: 24px;
      top: 42px;
    }

    .product-figure {
      position: absolute;
      inset: 0;
      display: grid;
      place-items: center;
      pointer-events: none;
    }

    .bag {
      width: min(54vw, 320px);
      aspect-ratio: 0.9;
      border-radius: 34px 34px 22px 22px;
      background:
        linear-gradient(180deg, rgba(255,255,255,0.55), rgba(255,255,255,0.1)),
        linear-gradient(160deg, #4e7f71, #274c43 70%, #1b2f2a);
      box-shadow: 0 24px 60px rgba(39, 76, 67, 0.28);
      position: relative;
      transform: rotate(-8deg);
    }

    .bag::before {
      content: "";
      position: absolute;
      left: 50%;
      top: -42px;
      width: 58%;
      height: 72px;
      border: 12px solid #274c43;
      border-bottom: 0;
      border-radius: 80px 80px 0 0;
      transform: translateX(-50%);
      background: transparent;
    }

    .bag::after {
      content: "ATELIER";
      position: absolute;
      left: 50%;
      top: 50%;
      transform: translate(-50%, -50%);
      color: rgba(255, 255, 255, 0.9);
      letter-spacing: 0.38em;
      font-size: 0.8rem;
      font-weight: 800;
    }

    .floating-chip {
      position: absolute;
      padding: 10px 14px;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.76);
      border: 1px solid rgba(255, 255, 255, 0.7);
