      font-size: 0.9rem;
      font-weight: 700;
    }

    .chip-top { top: 18px; left: 18px; }
    .chip-bottom { right: 18px; bottom: 18px; }

    .hero-mini {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    .mini-card {
      padding: 16px;
      border-radius: 20px;
      background: rgba(255, 255, 255, 0.72);
      border: 1px solid var(--line);
    }

    .mini-card strong {
      display: block;
      margin-bottom: 6px;
    }

    .section {
      padding: 10px 4px 0;
    }

    .section-head {
      display: flex;
      justify-content: space-between;
      align-items: end;
      gap: 16px;
      margin-bottom: 18px;
    }

    .section h2 {
      font-size: clamp(1.6rem, 2vw, 2.3rem);
      margin: 0;
      letter-spacing: -0.04em;
    }

    .section p.intro {
