      color: var(--muted);
      max-width: 60ch;
      line-height: 1.6;
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 18px;
    }

    .card {
      border-radius: 24px;
      overflow: hidden;
    }

    .card-visual {
      padding: 20px;
      min-height: 230px;
      display: grid;
      place-items: center;
      position: relative;
      overflow: hidden;
      background:
